<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Conway's Game of Life</title>
<style>
  :root {
    --bg: #0b0d12;
    --panel: #141822;
    --edge: #232a38;
    --ink: #e6ecf5;
    --muted: #8b96ab;
    --accent: #57e6a5;
    --accent2: #7aa2ff;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    padding: 0;
    background: var(--bg);
    color: var(--ink);
    font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
    min-height: 100%;
  }
  body {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 18px;
    padding: 24px 16px 40px;
  }
  h1 {
    margin: 0;
    font-size: 20px;
    letter-spacing: 3px;
    text-transform: uppercase;
    font-weight: 600;
    color: var(--ink);
  }
  h1 span { color: var(--accent); }
  .sub {
    margin: -10px 0 0;
    font-size: 12px;
    color: var(--muted);
    letter-spacing: 1px;
  }
  #wrap {
    padding: 10px;
    background: var(--panel);
    border: 1px solid var(--edge);
    border-radius: 14px;
    box-shadow: 0 18px 50px rgba(0,0,0,.55);
    line-height: 0;
  }
  #life {
    width: 600px;
    height: 600px;
    max-width: 86vmin;
    max-height: 86vmin;
    display: block;
    border-radius: 8px;
    background: #0d1017;
    cursor: crosshair;
    touch-action: none;
  }
  #controls {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
    justify-content: center;
    align-items: center;
  }
  button {
    font: inherit;
    font-size: 13px;
    letter-spacing: 1px;
    text-transform: uppercase;
    color: var(--ink);
    background: #1b2130;
    border: 1px solid var(--edge);
    border-radius: 10px;
    padding: 10px 18px;
    cursor: pointer;
    transition: transform .08s ease, background .15s ease, border-color .15s ease, color .15s ease;
  }
  button:hover { background: #242c3e; border-color: #35405a; }
  button:active { transform: translateY(1px); }
  button.on { background: var(--accent); border-color: var(--accent); color: #04140d; }
  #stats {
    font-size: 12px;
    color: var(--muted);
    letter-spacing: 1px;
    display: flex;
    gap: 18px;
  }
  #stats b { color: var(--accent2); font-weight: 600; }
  label.speed {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--muted);
    letter-spacing: 1px;
  }
  input[type=range] { accent-color: var(--accent); width: 110px; }
</style>
</head>
<body>

<h1>Game of <span>Life</span></h1>
<p class="sub">B3/S23 &middot; click or drag to paint</p>

<div id="wrap"><canvas id="life" width="600" height="600"></canvas></div>

<div id="controls">
  <button id="step">Step</button>
  <button id="play">Play</button>
  <button id="random">Random</button>
  <button id="clear">Clear</button>
  <label class="speed">Speed <input id="speed" type="range" min="1" max="60" value="12"></label>
</div>

<div id="stats">
  <span>gen <b id="gen">0</b></span>
  <span>alive <b id="alive">0</b></span>
</div>

<script>
(function () {
  "use strict";

  var W = 60, H = 60;                     // cells
  var canvas = document.getElementById("life");
  var ctx = canvas.getContext("2d");
  var CELL = canvas.width / W;            // device px per cell

  var cells = new Uint8Array(W * H);
  var next = new Uint8Array(W * H);
  var generation = 0;

  var genEl = document.getElementById("gen");
  var aliveEl = document.getElementById("alive");

  function idx(x, y) { return y * W + x; }

  function get(x, y) {
    x = x | 0; y = y | 0;
    if (x < 0 || y < 0 || x >= W || y >= H) return 0;
    return cells[idx(x, y)];
  }

  function set(x, y, v) {
    x = x | 0; y = y | 0;
    if (x < 0 || y < 0 || x >= W || y >= H) return;
    cells[idx(x, y)] = v ? 1 : 0;
  }

  function neighbours(x, y) {
    var n = 0;
    for (var dy = -1; dy <= 1; dy++) {
      for (var dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        n += get(x + dx, y + dy);
      }
    }
    return n;
  }

  // Simultaneous update: read from `cells`, write to `next`, then swap.
  function step() {
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        var n = neighbours(x, y);
        var a = cells[idx(x, y)];
        next[idx(x, y)] = (a ? (n === 2 || n === 3) : (n === 3)) ? 1 : 0;
      }
    }
    var tmp = cells; cells = next; next = tmp;
    generation++;
    draw();
  }

  function clear() {
    cells.fill(0);
    generation = 0;
    draw();
  }

  function randomize() {
    for (var i = 0; i < cells.length; i++) cells[i] = Math.random() < 0.28 ? 1 : 0;
    generation = 0;
    draw();
  }

  function draw() {
    var count = 0;

    ctx.fillStyle = "#0d1017";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // grid lines
    ctx.strokeStyle = "rgba(255,255,255,0.045)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (var g = 0; g <= W; g++) {
      var p = Math.round(g * CELL) + 0.5;
      ctx.moveTo(p, 0); ctx.lineTo(p, canvas.height);
      ctx.moveTo(0, p); ctx.lineTo(canvas.width, p);
    }
    ctx.stroke();

    // live cells
    for (var y = 0; y < H; y++) {
      for (var x = 0; x < W; x++) {
        if (!cells[idx(x, y)]) continue;
        count++;
        var hue = 140 + ((x + y + generation) % 60);
        ctx.fillStyle = "hsl(" + hue + ", 78%, 60%)";
        ctx.fillRect(x * CELL + 0.6, y * CELL + 0.6, CELL - 1.2, CELL - 1.2);
      }
    }

    genEl.textContent = generation;
    aliveEl.textContent = count;
  }

  /* ---------- painting ---------- */
  var painting = false, paintVal = 1, lastCell = -1;

  function cellFromEvent(e) {
    var r = canvas.getBoundingClientRect();
    var x = Math.floor((e.clientX - r.left) / r.width * W);
    var y = Math.floor((e.clientY - r.top) / r.height * H);
    if (x < 0 || y < 0 || x >= W || y >= H) return null;
    return { x: x, y: y };
  }

  canvas.addEventListener("pointerdown", function (e) {
    var c = cellFromEvent(e);
    if (!c) return;
    e.preventDefault();
    if (canvas.setPointerCapture) { try { canvas.setPointerCapture(e.pointerId); } catch (_) {} }
    painting = true;
    paintVal = get(c.x, c.y) ? 0 : 1;    // toggle based on first cell
    set(c.x, c.y, paintVal);
    lastCell = idx(c.x, c.y);
    draw();
  });

  canvas.addEventListener("pointermove", function (e) {
    if (!painting) return;
    var c = cellFromEvent(e);
    if (!c) return;
    var i = idx(c.x, c.y);
    if (i === lastCell) return;
    lastCell = i;
    set(c.x, c.y, paintVal);
    draw();
  });

  function endPaint() { painting = false; lastCell = -1; }
  window.addEventListener("pointerup", endPaint);
  window.addEventListener("pointercancel", endPaint);

  /* ---------- controls ---------- */
  var playBtn = document.getElementById("play");
  var speedEl = document.getElementById("speed");
  var timer = null;

  function stopLoop() {
    if (timer !== null) { clearInterval(timer); timer = null; }
    playBtn.classList.remove("on");
    playBtn.textContent = "Play";
  }

  function startLoop() {
    stopLoop();
    timer = setInterval(step, 1000 / Number(speedEl.value));
    playBtn.classList.add("on");
    playBtn.textContent = "Pause";
  }

  playBtn.addEventListener("click", function () {
    if (timer !== null) stopLoop(); else startLoop();
  });
  speedEl.addEventListener("input", function () { if (timer !== null) startLoop(); });

  document.getElementById("step").addEventListener("click", function () { step(); });
  document.getElementById("random").addEventListener("click", function () { randomize(); });
  document.getElementById("clear").addEventListener("click", function () { stopLoop(); clear(); });

  window.addEventListener("keydown", function (e) {
    if (e.code === "Space") { e.preventDefault(); playBtn.click(); }
    else if (e.key === "s" || e.key === "S") step();
    else if (e.key === "r" || e.key === "R") randomize();
    else if (e.key === "c" || e.key === "C") { stopLoop(); clear(); }
  });

  /* ---------- public API ---------- */
  window.life = {
    w: W,
    h: H,
    get: get,
    set: function (x, y, v) { set(x, y, v); draw(); },
    step: step,
    clear: clear
  };

  // seed a friendly starting soup
  randomize();
})();
</script>
</body>
</html>
